function getSum(a, b) {
  let res = 0;
  let carry = 0;
  for (let i = 0; i < 32; i++) {
    const bitA = (a >> i) & 1;
    const bitB = (b >> i) & 1;
    const sum = bitA ^ bitB ^ carry;
    carry = (bitA & bitB) | (bitA & carry) | (bitB & carry);
    res |= (sum << i);
  }
  return res;
}

function getSum(a, b) {
  while (b !== 0) {
    const carry = (a & b) << 1;
    a = a ^ b;
    b = carry;
  }
  return a;
}

def getSum(a: int, b: int) -> int:
    mask = 0xFFFFFFFF
    while (b & mask) != 0:
        carry = (a & b) << 1
        a = (a ^ b) & mask
        b = carry & mask
    return a if a <= 0x7FFFFFFF else ~(a ^ mask)
